// A pixel-exact stand-in for the LovyanGFX calls ui.cpp uses, drawing into a
// 320x240 buffer that is then pixel-doubled onto a canvas. Shapes transcribe
// LGFXBase.cpp's own Bresenham loops; text uses the device's glyph bitmaps
// from fonts.js (generated by tools/fonts2js.py). Colours pass through the
// panel's 16-bit RGB565 quantisation so the sim shows what the panel can.
//
// What it cannot show: the backlight, the IPS panel's viewing angle, and how
// the warm near-black reads in a room. Those remain a hardware check.
(function () {
  'use strict';

  const F = window.LGFX_FONTS;

  function b64(s) {
    const bin = atob(s), out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  for (const k in F) {
    const f = F[k];
    if (f.type === 'gfx') f.bitmap = b64(f.bitmap);
    else f.rows = b64(f.rows);
  }

  // Metrics as GFXfont::getDefaultMetric computes them.
  function gfxMetrics(f) {
    if (f._m) return f._m;
    let ab = 0, bb = 0;
    for (const g of f.glyphs) {
      const a = -g[5]; if (a > ab) ab = a;
      const b = g[2] - a; if (b > bb) bb = b;
    }
    return (f._m = { baseline: ab, height: ab + bb });
  }

  // 888 -> 565 -> 888, the way the panel and colour converter round-trip it.
  function quant(c) {
    let r = (c >> 16) & 0xff, g = (c >> 8) & 0xff, b = c & 0xff;
    r >>= 3; g >>= 2; b >>= 3;
    r = (r << 3) | (r >> 2); g = (g << 2) | (g >> 4); b = (b << 3) | (b >> 2);
    return (r << 16) | (g << 8) | b;
  }

  class LGFX {
    constructor(w = 320, h = 240) {
      this.w = w; this.h = h;
      this.px = new Uint32Array(w * h);      // 0xRRGGBB per pixel
      this.font = 'Font2';
      this.datum = 0;
      this.fg = 0xffffff; this.bg = 0x000000;
    }

    // ── raw pixels ──────────────────────────────────────
    drawPixel(x, y, c) {
      if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
      this.px[y * this.w + x] = quant(c);
    }
    fillRect(x, y, w, h, c) {
      if (w < 0) { x += w + 1; w = -w; }
      if (h < 0) { y += h + 1; h = -h; }
      const x0 = Math.max(0, x), y0 = Math.max(0, y);
      const x1 = Math.min(this.w, x + w), y1 = Math.min(this.h, y + h);
      const q = quant(c);
      for (let yy = y0; yy < y1; yy++)
        for (let xx = x0; xx < x1; xx++) this.px[yy * this.w + xx] = q;
    }
    fillScreen(c) { this.fillRect(0, 0, this.w, this.h, c); }

    // LGFXBase::fillRectAlpha -> Panel::writeFillRectAlphaPreclipped ->
    // effect_fill_alpha, verbatim. The destination channels are the QUANTIZED
    // ones, because the sprite is 16bpp and R8()/G8()/B8() expand back out of
    // 565 -- so blending has to happen after quant(), not before.
    fillRectAlpha(x, y, w, h, alpha, c) {
      const q = quant(c);
      const inv = 256 - alpha;
      const r8a = ((q >> 16) & 0xff) * (1 + alpha);
      const g8a = ((q >> 8) & 0xff) * (1 + alpha);
      const b8a = (q & 0xff) * (1 + alpha);
      const x0 = Math.max(0, x), y0 = Math.max(0, y);
      const x1 = Math.min(this.w, x + w), y1 = Math.min(this.h, y + h);
      for (let yy = y0; yy < y1; yy++)
        for (let xx = x0; xx < x1; xx++) {
          const i = yy * this.w + xx, d = this.px[i];
          this.px[i] = ((((r8a + ((d >> 16) & 0xff) * inv) >> 8) << 16)
                      | (((g8a + ((d >> 8) & 0xff) * inv) >> 8) << 8)
                      | ((b8a + (d & 0xff) * inv) >> 8));
        }
    }
    drawFastHLine(x, y, w, c) { this.fillRect(x, y, w, 1, c); }
    drawFastVLine(x, y, h, c) { this.fillRect(x, y, 1, h, c); }

    // LGFXBase::fillRoundRect, verbatim.
    fillRoundRect(x, y, w, h, r, c) {
      const y2 = y + r, y1 = y + h - r - 1;
      let ddF_y = -(r << 1);
      const delta = w + ddF_y;
      this.fillRect(x, y2, w, h + ddF_y, c);
      const x0 = x + r;
      let f = 1 - r, ddF_x = 1, len = 0;
      for (let i = 0; i <= r; i++) {
        len++;
        if (f >= 0) {
          this.fillRect(x0 - r, y2 - i, (r << 1) + delta, len, c);
          this.fillRect(x0 - r, y1 + i - len + 1, (r << 1) + delta, len, c);
          if (i === r) break;
          len = 0;
          this.drawFastHLine(x0 - i, y1 + r, (i << 1) + delta, c);
          ddF_y += 2; f += ddF_y;
          this.drawFastHLine(x0 - i, y2 - r, (i << 1) + delta, c);
          r--;
        }
        ddF_x += 2; f += ddF_x;
      }
    }

    // LGFXBase::drawRoundRect, verbatim.
    drawRoundRect(x, y, w, h, r, c) {
      w--; h--;
      let len = (r << 1) + 1;
      const y1 = y + h - r, y0 = y + r;
      this.drawFastVLine(x, y0 + 1, h - len, c);
      this.drawFastVLine(x + w, y0 + 1, h - len, c);
      const x1 = x + w - r, x0 = x + r;
      this.drawFastHLine(x0 + 1, y, w - len, c);
      this.drawFastHLine(x0 + 1, y + h, w - len, c);
      let f = 1 - r, ddF_y = -(r << 1), ddF_x = 1;
      len = 0;
      for (let i = 0; i <= r; i++) {
        len++;
        if (f >= 0) {
          this.drawFastHLine(x0 - i, y0 - r, len, c);
          this.drawFastHLine(x0 - i, y1 + r, len, c);
          this.drawFastHLine(x1 + i - len + 1, y1 + r, len, c);
          this.drawFastHLine(x1 + i - len + 1, y0 - r, len, c);
          this.drawFastVLine(x1 + r, y1 + i - len + 1, len, c);
          this.drawFastVLine(x0 - r, y1 + i - len + 1, len, c);
          this.drawFastVLine(x1 + r, y0 - i, len, c);
          this.drawFastVLine(x0 - r, y0 - i, len, c);
          len = 0; r--;
          ddF_y += 2; f += ddF_y;
        }
        ddF_x += 2; f += ddF_x;
      }
    }

    // LGFXBase::fillCircle + fillCircleHelper(corners=3, delta=0).
    fillCircle(x, y, r, c) {
      this.drawFastHLine(x - r, y, (r << 1) + 1, c);
      if (r <= 0) return;
      const delta = 1;
      let f = 1 - r, ddF_y = -(r << 1), ddF_x = 1, i = 0;
      do {
        let len = 0;
        while (f < 0) { f += (ddF_x += 2); ++len; }
        i += len;
        f += (ddF_y += 2);
        if (len) this.fillRect(x - r, y + i - len + 1, (r << 1) + delta, len, c);
        this.drawFastHLine(x - i, y + r, (i << 1) + delta, c);
        this.drawFastHLine(x - i, y - r, (i << 1) + delta, c);
        if (len) this.fillRect(x - r, y - i, (r << 1) + delta, len, c);
      } while (i < --r);
    }

    // LGFXBase::drawCircle, verbatim.
    drawCircle(x, y, r, c) {
      if (r <= 0) { this.drawPixel(x, y, c); return; }
      let f = 1 - r, ddF_y = -(r << 1), ddF_x = 1, i = 0, j = -1;
      do {
        while (f < 0) { ++i; f += (ddF_x += 2); }
        f += (ddF_y += 2);
        this.drawFastHLine(x - i, y + r, i - j, c);
        this.drawFastHLine(x - i, y - r, i - j, c);
        this.drawFastHLine(x + j + 1, y - r, i - j, c);
        this.drawFastHLine(x + j + 1, y + r, i - j, c);
        this.drawFastVLine(x + r, y + j + 1, i - j, c);
        this.drawFastVLine(x + r, y - i, i - j, c);
        this.drawFastVLine(x - r, y - i, i - j, c);
        this.drawFastVLine(x - r, y + j + 1, i - j, c);
        j = i;
      } while (i < --r);
    }

    // ── text ────────────────────────────────────────────
    setFont(name) { if (!F[name]) throw new Error('no font ' + name); this.font = name; }
    setTextDatum(d) { this.datum = d; }
    setTextColor(fg, bg) { this.fg = fg; this.bg = bg === undefined ? fg : bg; }

    fontHeight(name = this.font) {
      const f = F[name];
      return f.type === 'gfx' ? gfxMetrics(f).height : f.height;
    }

    _glyph(f, ch) {
      const code = ch.charCodeAt(0);
      if (f.type === 'gfx') {
        if (code < f.first || code > f.last) return null;
        return f.glyphs[code - f.first];
      }
      const i = code - 0x20;
      return i >= 0 && i < 96 ? i : null;
    }

    // LGFXBase::text_width.
    textWidth(s, name = this.font) {
      const f = F[name];
      if (!s) return 0;
      let left = 0, right = 0;
      for (const ch of s) {
        let xo = 0, xa, w;
        if (f.type === 'gfx') {
          const g = this._glyph(f, ch) || this._glyph(f, ' ');
          xa = g[3]; w = g[1]; xo = g[4];
        } else {
          const i = this._glyph(f, ch);
          xa = w = f.widths[i === null ? 0 : i];
        }
        if (left === 0 && right === 0 && xo < 0) left = right = -xo;
        right = left + Math.max(xa, w + xo);
        left += xa;
      }
      return right;
    }

    // LGFXBase::draw_string with the datum handling ui.cpp relies on.
    drawString(s, x, y, name = this.font) {
      const f = F[name];
      const cw = this.textWidth(s, name);
      const ch = this.fontHeight(name);
      const d = this.datum;
      if (d & 4) y -= ch >> 1; else if (d & 8) y -= ch;
      if (d & 1) x -= cw >> 1; else if (d & 2) x -= cw;
      let sumX = 0;
      if (f.type === 'gfx' && s) {
        const g0 = this._glyph(f, s[0]) || this._glyph(f, ' ');
        if (g0[4] < 0) sumX = -g0[4];
      }
      const fillbg = this.fg !== this.bg;
      for (const c of s) {
        if (f.type === 'gfx') sumX += this._drawGfx(f, x + sumX, y, c, fillbg);
        else sumX += this._drawBmp(f, x + sumX, y, c, fillbg);
      }
      return sumX;
    }

    _drawGfx(f, x, y, c, fillbg) {
      const m = gfxMetrics(f);
      let g = this._glyph(f, c);
      if (!g) { g = this._glyph(f, ' '); if (fillbg) this.fillRect(x, y, g[3], m.height, this.bg); return g[3]; }
      const [off, w, h, xa, xo, yo] = g;
      if (fillbg) {
        const left = x + (xo < 0 ? xo : 0), right = x + Math.max(w + xo, xa);
        this.fillRect(left, y, right - left, m.height, this.bg);
      }
      const gx = x + xo, gy = y + m.baseline + yo;
      let bit = off * 8;
      const q = quant(this.fg);
      for (let yy = 0; yy < h; yy++)
        for (let xx = 0; xx < w; xx++, bit++)
          if (f.bitmap[bit >> 3] & (0x80 >> (bit & 7))) {
            const px = gx + xx, py = gy + yy;
            if (px >= 0 && py >= 0 && px < this.w && py < this.h) this.px[py * this.w + px] = q;
          }
      return xa;
    }

    // draw_char_bmp with margin = 1: the last column is padding.
    _drawBmp(f, x, y, c, fillbg) {
      let i = this._glyph(f, c);
      if (i === null) i = 0;
      const fw = f.widths[i], bpr = (fw + 6) >> 3;
      let addr = 0;
      for (let k = 0; k < i; k++) addr += ((f.widths[k] + 6) >> 3) * f.height;
      if (fillbg) this.fillRect(x, y, fw, f.height, this.bg);
      const q = quant(this.fg);
      for (let yy = 0; yy < f.height; yy++) {
        for (let xx = 0; xx < fw - 1; xx++) {
          if (f.rows[addr + yy * bpr + (xx >> 3)] & (0x80 >> (xx & 7))) {
            const px = x + xx, py = y + yy;
            if (px >= 0 && py >= 0 && px < this.w && py < this.h) this.px[py * this.w + px] = q;
          }
        }
      }
      return fw;
    }

    // ── output ──────────────────────────────────────────
    // Pixel-doubled, never smoothed: the chunkiness is the point.
    blit(canvas, scale = 2) {
      const off = this._off || (this._off = document.createElement('canvas'));
      off.width = this.w; off.height = this.h;
      const octx = off.getContext('2d');
      const img = octx.createImageData(this.w, this.h);
      const d = img.data;
      for (let i = 0, j = 0; i < this.px.length; i++, j += 4) {
        const c = this.px[i];
        d[j] = c >> 16; d[j + 1] = (c >> 8) & 0xff; d[j + 2] = c & 0xff; d[j + 3] = 255;
      }
      octx.putImageData(img, 0, 0);
      canvas.width = this.w * scale; canvas.height = this.h * scale;
      canvas.style.width = canvas.width + 'px';
      const ctx = canvas.getContext('2d');
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(off, 0, 0, canvas.width, canvas.height);
    }
  }

  // Text datums, as LovyanGFX numbers them.
  LGFX.TL = 0; LGFX.TC = 1; LGFX.TR = 2;
  LGFX.ML = 4; LGFX.MC = 5; LGFX.MR = 6;
  LGFX.BL = 8; LGFX.BC = 9; LGFX.BR = 10;

  window.LGFX = LGFX;
})();
